namespace RcsMap {
 public sealed class SurfaceChoice {
  public string Id {get;set;} public string Label {get;set;}
  public override string ToString(){return Label;}
  public static List<SurfaceChoice> All(MapDocument d){var r=new List<SurfaceChoice>{new SurfaceChoice{Id=TerrainGeometry.Ground,Label="地面 · Z=0"}};if(d.Terrain!=null)r.AddRange(d.Terrain.Surfaces.Select(s=>new SurfaceChoice{Id=s.Id,Label=s.Name+" · "+s.Kind}));return r;}
 }
 public sealed class TerrainCanvas:Control {
  public MapDocument Document;public int View=0,SelectedPoint=-1;public string SelectedSurface;
  public Action<int> PointPicked;
  double yaw=-35,pitch=30,scale=1;Point last;bool rotate;
  readonly List<KeyValuePair<int,PointF>> hits=new List<KeyValuePair<int,PointF>>();
  public TerrainCanvas(){DoubleBuffered=true;Dock=DockStyle.Fill;BackColor=Color.FromArgb(245,248,252);}
  protected override void OnMouseDown(MouseEventArgs e){base.OnMouseDown(e);last=e.Location;foreach(var h in hits.OrderBy(h=>(h.Value.X-e.X)*(h.Value.X-e.X)+(h.Value.Y-e.Y)*(h.Value.Y-e.Y)))if(Math.Abs(h.Value.X-e.X)<14&&Math.Abs(h.Value.Y-e.Y)<14){SelectedPoint=h.Key;if(PointPicked!=null)PointPicked(h.Key);Invalidate();return;}if(View==2&&e.Button==MouseButtons.Left){rotate=true;Capture=true;}}
  protected override void OnMouseUp(MouseEventArgs e){rotate=false;Capture=false;base.OnMouseUp(e);}
  protected override void OnMouseMove(MouseEventArgs e){if(rotate){yaw+=(e.X-last.X)*.5;pitch=Math.Max(10,Math.Min(80,pitch+(e.Y-last.Y)*.3));last=e.Location;Invalidate();}base.OnMouseMove(e);}
  protected override void OnMouseWheel(MouseEventArgs e){scale=Math.Max(.4,Math.Min(2.5,scale*Math.Pow(1.1,e.Delta/120.0)));Invalidate();base.OnMouseWheel(e);}
  protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);Draw(e.Graphics,ClientRectangle);}
  public void Draw(Graphics g,Rectangle bounds){g.Clear(BackColor);g.SmoothingMode=SmoothingMode.AntiAlias;hits.Clear();if(Document==null||bounds.Width<30||bounds.Height<30)return;try{if(View==1)Profile(g,bounds);else Scene(g,bounds);}catch(Exception e){g.DrawString("请修正地形参数："+e.Message,Font,Brushes.Firebrick,15,50);}}
  PointF Raw(double x,double y,double z){if(View==0)return new PointF((float)x,(float)-y);double a=yaw*Math.PI/180,p=pitch*Math.PI/180;return new PointF((float)(x*Math.Cos(a)-y*Math.Sin(a)),(float)(-(x*Math.Sin(a)+y*Math.Cos(a))*Math.Sin(p)-z*Math.Cos(p)));}
  static bool Finite(PointF p){return MapDocument.Finite(p.X)&&MapDocument.Finite(p.Y);}
  public static Color SurfaceColor(TerrainSurface s){return s.Id==TerrainGeometry.Ground?Color.FromArgb(238,242,246):s.Kind==SurfaceKind.水平平台?Color.FromArgb(169,207,234):Color.FromArgb(239,202,137);}
  void Scene(Graphics g,Rectangle b){var d=Document;var all=new List<TerrainSurface>{TerrainGeometry.Surface(d,null)};if(d.Terrain!=null)all.AddRange(d.Terrain.Surfaces);var allraw=new List<PointF>();foreach(var s in all){if(s.Width<=0||s.Depth<=0)continue;allraw.AddRange(Corners(s).Select(c=>Raw(c[0],c[1],c[2])).Where(Finite));}if(allraw.Count==0)return;
   float minx=allraw.Min(p=>p.X),maxx=allraw.Max(p=>p.X),miny=allraw.Min(p=>p.Y),maxy=allraw.Max(p=>p.Y);double k=Math.Min((b.Width-130)/Math.Max(1,maxx-minx),(b.Height-140)/Math.Max(1,maxy-miny))*scale;
   Func<double,double,double,PointF> screen=(x,y,z)=>{var q=Raw(x,y,z);return new PointF((float)(b.Width/2+(q.X-(minx+maxx)/2)*k),(float)(b.Height/2+20+(q.Y-(miny+maxy)/2)*k));};
   g.DrawString(View==0?"俯视 · 点击航点同步选择；用归属表指定楼层":"三维几何预览 · 拖动旋转视角 / 滚轮缩放",Font,Brushes.SlateGray,12,12);
   g.DrawString("Z为地图规划高度；预览绘制上表面，净空计入配置厚度；尚无坡道控制",Font,Brushes.SaddleBrown,12,33);
   // Surface centers sorted back-to-front in the current camera, with the ground first.
   foreach(var s in all.OrderBy(s=>s.Id==TerrainGeometry.Ground?Double.MinValue:s.Z0+s.Z1+((s.X+s.Width/2)*Math.Sin(yaw*Math.PI/180)+(s.Y+s.Depth/2)*Math.Cos(yaw*Math.PI/180))*.05)){
    if(s.Width<=0||s.Depth<=0)continue;var poly=Corners(s).Select(c=>screen(c[0],c[1],c[2])).ToArray();if(poly.Any(p=>!Finite(p)))continue;
    using(var brush=new SolidBrush(Color.FromArgb(View==0&&s.Id!=SelectedSurface?110:190,SurfaceColor(s))))g.FillPolygon(brush,poly);using(var pen=new Pen(s.Id==SelectedSurface?Color.DarkOrange:Color.SlateGray,s.Id==SelectedSurface?3:1))g.DrawPolygon(pen,poly);
    if(s.Id!=TerrainGeometry.Ground)g.DrawString(s.Name+" · "+s.Z0.ToString("0")+(s.Kind==SurfaceKind.水平平台?"":"→"+s.Z1.ToString("0"))+" mm",Font,Brushes.DarkSlateGray,poly[0]);
   }
   foreach(var o in d.Obstacles){var s=TerrainGeometry.Surface(d,o.SurfaceId);if(s==null)continue;var pts=new[]{screen(o.X,o.Y,s.HeightAt(o.X,o.Y)),screen(o.X+o.Width,o.Y,s.HeightAt(o.X+o.Width,o.Y)),screen(o.X+o.Width,o.Y+o.Height,s.HeightAt(o.X+o.Width,o.Y+o.Height)),screen(o.X,o.Y+o.Height,s.HeightAt(o.X,o.Y+o.Height))};using(var pen=new Pen(Color.IndianRed,2))g.DrawPolygon(pen,pts);}
   for(int i=1;i<d.Points.Count;i++){var a=d.Points[i-1];var c=d.Points[i];TerrainLeg l;string error;bool valid=TerrainGeometry.TryLeg(d,a,c,out l,out error);using(var pen=new Pen(valid?Color.FromArgb(32,111,200):Color.Firebrick,3)){if(!valid)pen.DashStyle=DashStyle.Dash;if(valid&&l.From.Id!=l.To.Id){double t=l.Handoff,x=a.X+(c.X-a.X)*t,y=a.Y+(c.Y-a.Y)*t,z=l.From.HeightAt(x,y);g.DrawLines(pen,new[]{screen(a.X,a.Y,l.Z0),screen(x,y,z),screen(c.X,c.Y,l.Z1)});}else g.DrawLine(pen,screen(a.X,a.Y,SafeZ(d,a)),screen(c.X,c.Y,SafeZ(d,c)));}}
   // In top view, selected-surface nodes are drawn last so bridge/ground picks remain explicit.
   foreach(int i in Enumerable.Range(0,d.Points.Count).OrderBy(i=>TerrainGeometry.Key(d.Points[i].SurfaceId)==SelectedSurface?1:0)){
    var p=d.Points[i];double z=SafeZ(d,p);PointF q=screen(p.X,p.Y,z);hits.Add(new KeyValuePair<int,PointF>(i,q));using(var brush=new SolidBrush(i==SelectedPoint?Color.DarkOrange:Color.RoyalBlue))g.FillEllipse(brush,q.X-7,q.Y-7,14,14);g.DrawString("P"+i+" · Z="+z.ToString("0.##"),Font,Brushes.DarkSlateBlue,q.X+10,q.Y+4);
   }
  }
  static double SafeZ(MapDocument d,Waypoint p){double z=TerrainGeometry.Height(d,p);return MapDocument.Finite(z)?z:0;}
  static IEnumerable<double[]> Corners(TerrainSurface s){foreach(var p in new[]{new[]{s.X,s.Y},new[]{s.X+s.Width,s.Y},new[]{s.X+s.Width,s.Y+s.Depth},new[]{s.X,s.Y+s.Depth}})yield return new[]{p[0],p[1],s.HeightAt(p[0],p[1])};}
  void Profile(Graphics g,Rectangle b){var d=Document;g.DrawString("路线侧视 · 横轴为累计水平路程，纵轴为规划高度；竖直比例独立缩放",Font,Brushes.SlateGray,12,12);g.DrawString("点击节点联动归属表。红虚线表示不连通；几何预览不代表实车控制验证。",Font,Brushes.SaddleBrown,12,33);if(d.Points.Count==0)return;
   double[] dist=new double[d.Points.Count];for(int i=1;i<dist.Length;i++){double dx=d.Points[i].X-d.Points[i-1].X,dy=d.Points[i].Y-d.Points[i-1].Y;dist[i]=dist[i-1]+Math.Sqrt(dx*dx+dy*dy);}double maxz=Math.Max(300,d.Points.Max(p=>SafeZ(d,p))*1.2),length=Math.Max(1,dist.Last());
   Func<double,double,PointF> screen=(x,z)=>new PointF((float)(65+x/length*(b.Width-150)),(float)(b.Height-65-z/maxz*(b.Height-150)));
   using(var pen=new Pen(Color.LightSteelBlue))for(int i=0;i<=4;i++){double z=maxz*i/4;var p=screen(0,z);g.DrawLine(pen,p.X,p.Y,b.Width-35,p.Y);g.DrawString(z.ToString("0")+" mm",Font,Brushes.SlateGray,3,p.Y-10);}
   for(int i=1;i<dist.Length;i++){TerrainLeg leg;string error;bool valid=TerrainGeometry.TryLeg(d,d.Points[i-1],d.Points[i],out leg,out error);using(var pen=new Pen(valid?Color.RoyalBlue:Color.Firebrick,3)){if(!valid)pen.DashStyle=DashStyle.Dash;if(valid&&leg.From.Id!=leg.To.Id){double t=leg.Handoff;double x=d.Points[i-1].X+(d.Points[i].X-d.Points[i-1].X)*t,y=d.Points[i-1].Y+(d.Points[i].Y-d.Points[i-1].Y)*t;g.DrawLines(pen,new[]{screen(dist[i-1],leg.Z0),screen(dist[i-1]+(dist[i]-dist[i-1])*t,leg.From.HeightAt(x,y)),screen(dist[i],leg.Z1)});}else g.DrawLine(pen,screen(dist[i-1],SafeZ(d,d.Points[i-1])),screen(dist[i],SafeZ(d,d.Points[i])));}
    if(valid){var mid=screen((dist[i-1]+dist[i])/2,(leg.Z0+leg.Z1)/2);g.DrawString("路程 "+leg.Length.ToString("0")+" mm · 坡度 "+leg.From.Slope.ToString("0.0")+" / "+leg.To.Slope.ToString("0.0")+"°",Font,Brushes.DarkSlateGray,mid.X-35,mid.Y-38);}}
   for(int i=0;i<dist.Length;i++){var p=screen(dist[i],SafeZ(d,d.Points[i]));hits.Add(new KeyValuePair<int,PointF>(i,p));g.FillEllipse(i==SelectedPoint?Brushes.DarkOrange:Brushes.RoyalBlue,p.X-6,p.Y-6,12,12);g.DrawString("P"+i+"\n"+dist[i].ToString("0")+" mm",Font,Brushes.DarkSlateGray,p.X-10,p.Y+10);}
  }
 }
 public sealed class TerrainDialog:Form {
  public MapDocument Document {get;private set;}
  ListBox surfaces=new ListBox(),connections=new ListBox();PropertyGrid props=new PropertyGrid();ComboBox ca=new ComboBox(),cb=new ComboBox();DataGridView assignments=new DataGridView(),obstacles=new DataGridView();Label status=new Label();TerrainCanvas[] views=new TerrainCanvas[3];bool refresh;
  TabControl previewTabs=new TabControl{Dock=DockStyle.Fill};
  public TerrainDialog(MapDocument source){Document=source.Clone();if(Document.Terrain==null)Document.Terrain=new TerrainMap();Document.Version=4;Text="立体地形 · 平台 / 坡道 / 多层地图";Size=new Size(1280,850);MinimumSize=new Size(1050,700);StartPosition=FormStartPosition.CenterParent;Font=new Font("Microsoft YaHei UI",9);
   var root=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2,RowCount=2,Padding=new Padding(8)};root.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,350));root.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));root.RowStyles.Add(new RowStyle(SizeType.Percent,100));root.RowStyles.Add(new RowStyle(SizeType.Absolute,86));Controls.Add(root);
   var data=new TabControl{Dock=DockStyle.Fill};root.Controls.Add(data,0,0);var st=new TabPage("表面");var ct=new TabPage("连接");var pt=new TabPage("航点归属");var ot=new TabPage("障碍归属");data.TabPages.AddRange(new[]{st,ct,pt,ot});
   var layout=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=3};layout.RowStyles.Add(new RowStyle(SizeType.Absolute,160));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,70));layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));st.Controls.Add(layout);surfaces.Dock=DockStyle.Fill;layout.Controls.Add(surfaces);var buttons=new FlowLayoutPanel{Dock=DockStyle.Fill};layout.Controls.Add(buttons);AddButton(buttons,"＋平台",()=>Add(false));AddButton(buttons,"＋坡道",()=>Add(true));AddButton(buttons,"删除",Delete);AddButton(buttons,"车体/能力参数",()=>{props.SelectedObject=Document.Terrain;});props.Dock=DockStyle.Fill;props.HelpVisible=true;props.ToolbarVisible=false;layout.Controls.Add(props);
   surfaces.SelectedIndexChanged+=(s,e)=>{if(surfaces.SelectedItem is TerrainSurface){props.SelectedObject=surfaces.SelectedItem;foreach(var v in views)if(v!=null){v.SelectedSurface=((TerrainSurface)surfaces.SelectedItem).Id;v.Invalidate();}}};props.PropertyValueChanged+=(s,e)=>RefreshAll();
   var cbars=new FlowLayoutPanel{Dock=DockStyle.Top,Height=150,FlowDirection=FlowDirection.TopDown};ct.Controls.Add(connections);connections.Dock=DockStyle.Fill;ct.Controls.Add(cbars);foreach(var box in new[]{ca,cb}){box.Width=310;box.DropDownStyle=ComboBoxStyle.DropDownList;cbars.Controls.Add(box);}AddButton(cbars,"添加通行连接",Connect);AddButton(cbars,"删除选中连接",()=>{int i=connections.SelectedIndex;if(i>=0){Document.Terrain.Connections.RemoveAt(i);RefreshAll();}});cbars.Controls.Add(new Label{Text="必须等高接边；投影重叠不会自动连接。",AutoSize=true});
   ConfigureGrid(assignments,pt,false);ConfigureGrid(obstacles,ot,true);
   var flow=new Button{Text="编辑选中航点流程 / 纠错",Dock=DockStyle.Bottom,Height=36};flow.Click+=(s,e)=>EditPointFlow();pt.Controls.Add(flow);flow.BringToFront();props.SelectedObject=Document.Terrain;
   root.Controls.Add(previewTabs,1,0);string[] names={"俯视图","路线侧视图","三维预览"};for(int i=0;i<3;i++){var page=new TabPage(names[i]);views[i]=new TerrainCanvas{Document=Document,View=i};views[i].PointPicked=SelectPoint;page.Controls.Add(views[i]);previewTabs.TabPages.Add(page);}
   var bottom=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2};bottom.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));bottom.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,280));root.Controls.Add(bottom,0,1);root.SetColumnSpan(bottom,2);status.Dock=DockStyle.Fill;status.AutoEllipsis=true;bottom.Controls.Add(status);var controls=new FlowLayoutPanel{Dock=DockStyle.Fill};bottom.Controls.Add(controls);AddButton(controls,"检查地图",()=>RefreshAll());var ok=new Button{Text="应用地形",Width=95,Height=30};ok.Click+=(s,e)=>{var errors=Document.Validate(false);if(errors.Count>0){MessageBox.Show(this,String.Join("\r\n",errors.Take(14).ToArray()),"请先修正地图");return;}DialogResult=DialogResult.OK;};controls.Controls.Add(ok);controls.Controls.Add(new Button{Text="取消",DialogResult=DialogResult.Cancel,Width=65,Height=30});AcceptButton=ok;CancelButton=controls.Controls.OfType<Button>().Last();RefreshAll();
  }
  static void AddButton(Control parent,string name,Action action){var b=new Button{Text=name,AutoSize=true,Height=29};b.Click+=(s,e)=>action();parent.Controls.Add(b);}
  void ConfigureGrid(DataGridView grid,Control parent,bool obs){grid.Dock=DockStyle.Fill;grid.AllowUserToAddRows=grid.AllowUserToDeleteRows=false;grid.RowHeadersVisible=false;grid.AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill;grid.SelectionMode=DataGridViewSelectionMode.FullRowSelect;grid.Columns.Add(new DataGridViewTextBoxColumn{HeaderText="编号",ReadOnly=true,FillWeight=40});grid.Columns.Add(new DataGridViewComboBoxColumn{HeaderText="所属表面",DisplayMember="Label",ValueMember="Id",FillWeight=130});grid.Columns.Add(new DataGridViewTextBoxColumn{HeaderText="规划Z mm",ReadOnly=true,FillWeight=60});parent.Controls.Add(grid);
   grid.SelectionChanged+=(s,e)=>{if(refresh||obs||grid.CurrentRow==null)return;foreach(var v in views)if(v!=null){v.SelectedPoint=grid.CurrentRow.Index;v.Invalidate();}};
   grid.CurrentCellDirtyStateChanged+=(s,e)=>{if(grid.IsCurrentCellDirty)grid.CommitEdit(DataGridViewDataErrorContexts.Commit);};grid.DataError+=(s,e)=>{e.ThrowException=false;};grid.CellValueChanged+=(s,e)=>{if(refresh||e.RowIndex<0||e.ColumnIndex!=1)return;string id=Convert.ToString(grid.Rows[e.RowIndex].Cells[1].Value);if(obs)Document.Obstacles[e.RowIndex].SurfaceId=id==TerrainGeometry.Ground?null:id;else Document.Points[e.RowIndex].SurfaceId=id==TerrainGeometry.Ground?null:id;RefreshAll();SelectPoint(obs?-1:e.RowIndex);};
  }
  void Add(bool ramp){if(Document.Terrain.Surfaces.Count>=64)return;var s=new TerrainSurface{Name=ramp?"新坡道":"新平台",Kind=ramp?SurfaceKind.沿X直坡道:SurfaceKind.水平平台,X=500,Y=500,Z0=0,Z1=ramp?200:0,SpeedLimit=Math.Min(200,Document.Settings.MaxSpeed)};Document.Terrain.Surfaces.Add(s);RefreshAll();surfaces.SelectedItem=s;}
  void Delete(){var s=surfaces.SelectedItem as TerrainSurface;if(s==null)return;if(Document.Points.Any(p=>p.SurfaceId==s.Id)||Document.Obstacles.Any(o=>o.SurfaceId==s.Id)||Document.Terrain.Connections.Any(c=>c.A==s.Id||c.B==s.Id)){MessageBox.Show(this,"表面仍被航点、障碍或连接引用，请先修改归属并删除连接。");return;}Document.Terrain.Surfaces.Remove(s);props.SelectedObject=null;RefreshAll();}
  void Connect(){var a=ca.SelectedItem as SurfaceChoice;var b=cb.SelectedItem as SurfaceChoice;if(a==null||b==null||a.Id==b.Id)return;if(Document.Terrain.Connections.Any(c=>(c.A==a.Id&&c.B==b.Id)||(c.A==b.Id&&c.B==a.Id)))return;var sa=TerrainGeometry.Surface(Document,a.Id);var sb=TerrainGeometry.Surface(Document,b.Id);if(!TerrainGeometry.SurfacesMeet(sa,sb)){MessageBox.Show(this,"两个表面没有等高接合边。请先调整位置、高度或添加坡道。");return;}Document.Terrain.Connections.Add(new SurfaceConnection{A=a.Id,B=b.Id});RefreshAll();}
  void EditPointFlow(){if(assignments.CurrentRow==null)return;int index=assignments.CurrentRow.Index;var candidate=Document.Clone();using(var dialog=new PhaseDialog(candidate.Points[index],candidate.ActionIncludes))if(dialog.ShowDialog(this)==DialogResult.OK){Document.Points[index]=candidate.Points[index];Document.ActionIncludes=dialog.SharedIncludes;RefreshAll();SelectPoint(index);}}
  void SelectPoint(int index){foreach(var v in views){v.SelectedPoint=index;v.Invalidate();}if(index>=0&&index<assignments.Rows.Count){assignments.ClearSelection();assignments.Rows[index].Selected=true;assignments.CurrentCell=assignments.Rows[index].Cells[0];}}
  void RefreshAll(){if(refresh)return;refresh=true;try{object inspected=props.SelectedObject;var selected=surfaces.SelectedItem;surfaces.Items.Clear();foreach(var s in Document.Terrain.Surfaces)surfaces.Items.Add(s);if(selected!=null&&surfaces.Items.Contains(selected))surfaces.SelectedItem=selected;var choices=SurfaceChoice.All(Document);foreach(var box in new[]{ca,cb}){string key=box.SelectedItem is SurfaceChoice?((SurfaceChoice)box.SelectedItem).Id:null;box.Items.Clear();box.Items.AddRange(choices.Cast<object>().ToArray());box.SelectedIndex=Math.Max(0,choices.FindIndex(c=>c.Id==key));}connections.Items.Clear();foreach(var c in Document.Terrain.Connections)connections.Items.Add((TerrainGeometry.Surface(Document,c.A)??new TerrainSurface{Name="已删除"}).Name+" ↔ "+(TerrainGeometry.Surface(Document,c.B)??new TerrainSurface{Name="已删除"}).Name);
    ((DataGridViewComboBoxColumn)assignments.Columns[1]).DataSource=choices.ToList();((DataGridViewComboBoxColumn)obstacles.Columns[1]).DataSource=choices.ToList();assignments.Rows.Clear();for(int i=0;i<Document.Points.Count;i++){var p=Document.Points[i];assignments.Rows.Add("P"+i,TerrainGeometry.Key(p.SurfaceId),TerrainGeometry.Height(Document,p).ToString("0.##"));}obstacles.Rows.Clear();for(int i=0;i<Document.Obstacles.Count;i++){var o=Document.Obstacles[i];var s=TerrainGeometry.Surface(Document,o.SurfaceId);obstacles.Rows.Add("障碍"+i,TerrainGeometry.Key(o.SurfaceId),s==null?"无效":s.HeightAt(o.X,o.Y).ToString("0.##"));}
    List<string> errors;try{errors=Document.Validate(false);}catch(Exception e){errors=new List<string>{e.Message};}status.Text=errors.Count==0?"✓ 地图几何检查通过。高度是规划值；立体路线仅编辑/预览，不生成坡道控制。":"⚠ "+String.Join(" / ",errors.Take(3).ToArray());status.ForeColor=errors.Count==0?Color.Teal:Color.Firebrick;foreach(var v in views)v.Invalidate();if(inspected==Document.Terrain||Document.Terrain.Surfaces.Contains(inspected as TerrainSurface))props.SelectedObject=inspected;props.Refresh();
   }finally{refresh=false;}}
  public void SelectView(int view){previewTabs.SelectedIndex=Math.Max(0,Math.Min(2,view));if(surfaces.Items.Count>0)surfaces.SelectedIndex=0;}
 }
}
